INSERT INTO items
    (id, name, ko_name, category, fling_power, description, effect)
VALUES
    (1697, 'ability-shield', NULL, 'held-items', NULL, NULL, NULL),
    (713, 'abomasite', '눈설왕나이트', 'mega-stones', 80, '눈설왕에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Abomasnow to Mega Evolve into Mega Abomasnow.'),
    (716, 'absolite', '앱솔나이트', 'mega-stones', 80, '앱솔에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Absol to Mega Evolve into Mega Absol.'),
    (2265, 'absolite-z', NULL, 'mega-stones', 80, NULL, NULL),
    (588, 'absorb-bulb', '구근', 'held-items', 30, '단 한 번 쓰면 없어지는 구근. 지니게 하고 물 기술을 받으면 특수공격이 올라간다.', 'Held: Raises the holder’s Special Attack by one stage when it takes Water-type damage.'),
    (112, 'adamant-orb', '금강옥', 'species-specific', 60, '디아루가에게 지니게 하면 드래곤과 강철타입 기술의 위력이 올라가는 반짝반짝 빛나는 구슬.', 'Boosts the damage from Dialga’s Dragon-type and Steel-type moves by 20%.'),
    (883, 'adrenaline-orb', '주눅구슬', 'held-items', 30, '포켓몬에게 지니게 하면 위협을 받았을 때 스피드가 올라간다.', 'Makes wild Pokémon more likely to summon allies.  Held: increases the holder’s Speed by one stage when affected by Intimidate.'),
    (711, 'aerodactylite', '프테라나이트', 'mega-stones', 80, '프테라에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Aerodactyl to Mega Evolve into Mega Aerodactyl.'),
    (706, 'aggronite', '보스로라나이트', 'mega-stones', 80, '보스로라에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Aggron to Mega Evolve into Mega Aggron.'),
    (139, 'aguav-berry', '아바열매', 'picky-healing', 10, '포켓몬에게 지니게 하면 위급할 때 HP를 회복한다. 싫어하는 맛이면 혼란에 빠진다.', 'Held: Consumed at 1/2 max HP to restore 1/8 max HP. Confuses Pokémon that dislike bitter flavor.'),
    (584, 'air-balloon', '풍선', 'held-items', 10, '포켓몬에게 지니게 하면 포켓몬이 허공에 뜬다. 공격을 받으면 터져버린다.', 'Held: Grants immunity to Ground-type moves, Spikes, and Toxic Spikes. Consumed when the holder takes damage from a move.'),
    (718, 'alakazite', '후디나이트', 'mega-stones', 80, '후딘에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Alakazam to Mega Evolve into Mega Alakazam.'),
    (796, 'altarianite', '파비코리나이트', 'mega-stones', 80, '파비코리에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Altaria to Mega Evolve into Mega Altaria.'),
    (697, 'ampharosite', '전룡나이트', 'mega-stones', 80, '전룡에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Ampharos to Mega Evolve into Mega Ampharos.'),
    (182, 'apicot-berry', '규살열매', 'in-a-pinch', 10, '포켓몬에게 지니게 하면 위급할 때 자신의 특수방어가 올라간다.', 'Held: Consumed at 1/4 max HP to boost Special Defense.'),
    (683, 'assault-vest', '돌격조끼', 'held-items', 80, '공격적으로 변하는 조끼. 지니게 하면 특수방어가 올라가지만 변화 기술을 쓸 수 없게 된다.', 'Raises the holder’s Special Defense to 1.5×.  Prevents the holder from selecting a status move.'),
    (798, 'audinite', '다부니나이트', 'mega-stones', 80, '다부니에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Audino to Mega Evolve into Mega Audino.'),
    (176, 'babiri-berry', '바리비열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 강철 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Steel-type attack to halve the damage.'),
    (707, 'banettite', '다크펫나이트', 'mega-stones', 80, '다크펫에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Banette to Mega Evolve into Mega Banette.'),
    (2255, 'barbaracite', NULL, 'mega-stones', 80, NULL, NULL),
    (2275, 'baxcalibrite', NULL, 'mega-stones', 80, NULL, NULL),
    (811, 'beedrillite', '독침붕나이트', 'mega-stones', 80, '독침붕에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Beedrill to Mega Evolve into Mega Beedrill.'),
    (273, 'big-root', '큰뿌리', 'held-items', 10, '지니게 하면 HP 흡수 기술을 썼을 때 여느 때보다 많은 HP를 자신이 회복할 수 있다.', 'Held: Increases HP recovered from draining moves, Ingrain, and Aqua Ring by 3/10 (30%).'),
    (587, 'binding-band', '조임밴드', 'held-items', 30, '조이기 기술을 보조하는 밴드. 지니게 하면 조이기 기술의 위력이 강해진다.', 'Held: Doubles the per-turn damage of multi-turn trapping moves.'),
    (218, 'black-belt', '검은띠', 'type-enhancement', 30, '마음을 긴장시키는 띠. 지니게 하면 격투타입 기술의 위력이 올라간다.', 'Held: Fighting-Type moves from holder do 20% more damage.'),
    (217, 'black-glasses', '검은안경', 'type-enhancement', 30, '괴상하게 보이는 안경. 지니게 하면 악타입 기술의 위력이 올라간다.', 'Held: Dark-Type moves from holder do 20% more damage.'),
    (258, 'black-sludge', '검은오물', 'held-items', 30, '지니게 하면 독타입의 포켓몬은 조금씩 HP를 회복한다. 그 이외의 타입은 HP가 줄어 버린다.', 'Held: Poison-type holder recovers 1/16 (6.25%) max HP each turn. Non-Poison-Types take 1/8 (12.5%) max HP damage.'),
    (1662, 'blank-plate', NULL, 'plates', NULL, NULL, NULL),
    (700, 'blastoisinite', '거북왕나이트', 'mega-stones', 80, '거북왕에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Blastoise to Mega Evolve into Mega Blastoise.'),
    (703, 'blazikenite', '번치코나이트', 'mega-stones', 80, '번치코에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Blaziken to Mega Evolve into Mega Blaziken.'),
    (1179, 'blunder-policy', '허탕보험', 'held-items', 80, '명중률에 의해 기술이 빗나갔을 때 스피드가 크게 올라간다.', NULL),
    (1696, 'booster-energy', NULL, 'held-items', NULL, NULL, NULL),
    (190, 'bright-powder', '반짝가루', 'held-items', 10, '반짝반짝 빛나는 가루. 지니게 하면 빛이 상대를 혼란시켜 기술이 명중되기 어려워진다.', 'Held: Increases the holder’s evasion by 1/9 (11 1/9%).'),
    (565, 'burn-drive', '블레이즈카세트', 'species-specific', 70, '게노세크트에게 지니게 하면 테크노버스터라는 기술이 불꽃타입으로 바뀌는 카세트.', 'Grants Genesect a red, Fire-type Techno Blast.'),
    (808, 'cameruptite', '폭타나이트', 'mega-stones', 80, '폭타에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Camerupt to Mega Evolve into Mega Camerupt.'),
    (589, 'cell-battery', '충전지', 'held-items', 30, '단 한 번 쓰면 없어지는 충전지. 지니게 하고 전기 기술을 받으면 공격이 올라간다.', 'Held: Raises the holder’s Attack by one stage when it takes Electric-type damage.'),
    (2248, 'chandelurite', NULL, 'mega-stones', 80, NULL, NULL),
    (226, 'charcoal', '목탄', 'type-enhancement', 30, '물건을 태우는 연료. 지니게 하면 불꽃타입 기술의 위력이 올라간다.', 'Held: Fire-Type moves from holder do 20% more damage.'),
    (699, 'charizardite-x', '리자몽나이트X', 'mega-stones', 80, '리자몽에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Charizard to Mega Evolve into Mega Charizard X.'),
    (717, 'charizardite-y', '리자몽나이트Y', 'mega-stones', 80, '리자몽에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Charizard to Mega Evolve into Mega Charizard Y.'),
    (172, 'charti-berry', '루미열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 바위 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Rock-type attack to halve the damage.'),
    (2249, 'chesnaughtite', NULL, 'mega-stones', 80, NULL, NULL),
    (177, 'chilan-berry', '카리열매', 'type-protection', 10, '포켓몬에게 지니게 하면 노말 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a Normal-type attack to halve the damage.'),
    (566, 'chill-drive', '프리즈카세트', 'species-specific', 70, '게노세크트에게 지니게 하면 테크노버스터라는 기술이 얼음타입으로 바뀌는 카세트.', 'Grants Genesect a white, Ice-type Techno Blast.'),
    (2264, 'chimechite', NULL, 'mega-stones', 80, NULL, NULL),
    (197, 'choice-band', '구애머리띠', 'choice', 10, '기술을 구애받는 머리띠. 지니게 하면 공격은 올라가지만 똑같은 기술밖에 쓰지 못한다.', 'Held: Increases Attack by 50%, but restricts the holder to only one move.'),
    (264, 'choice-scarf', '구애스카프', 'choice', 10, '기술을 구애받는 스카프. 지니게 하면 스피드는 올라가지만 같은 기술밖에 쓸 수 없다.', 'Held: Increases Speed by 50%, but restricts the holder to only one move.'),
    (274, 'choice-specs', '구애안경', 'choice', 10, '기술을 구애받는 안경. 지니게 하면 특수공격이 올라가지만 같은 기술밖에 쓸 수 없다.', 'Held: Increases Special Attack by 50%, but restricts the holder to only one move.'),
    (166, 'chople-berry', '로플열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 격투 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Fighting-type attack to halve the damage.'),
    (1698, 'clear-amulet', NULL, 'held-items', NULL, NULL, NULL),
    (2233, 'clefablite', NULL, 'mega-stones', 80, NULL, NULL),
    (169, 'coba-berry', '바코열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 비행 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Flying-type attack to halve the damage.'),
    (175, 'colbur-berry', '마코열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 악 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Dark-type attack to halve the damage.'),
    (2108, 'cornerstone-mask', NULL, 'held-items', NULL, NULL, NULL),
    (1701, 'covert-cloak', NULL, 'held-items', NULL, NULL, NULL),
    (2271, 'crabominite', NULL, 'mega-stones', 80, NULL, NULL),
    (187, 'custap-berry', '애슈열매', 'in-a-pinch', 10, '포켓몬에게 지니게 하면 위급할 때 한 번만 행동이 빨라진다.', 'Held: Consumed at 1/4 max HP when using a move to go first.'),
    (262, 'damp-rock', '축축한바위', 'held-items', 60, '지니게 한 포켓몬이 비바라기를 쓰면 여느 때보다 비 내리는 시간이 길어진다.', 'Held: Rain Dance by the holder lasts 8 rounds instead of 5.'),
    (2242, 'darkranite', NULL, 'mega-stones', 80, NULL, NULL),
    (204, 'deep-sea-scale', '심해의비늘', 'species-specific', 30, '진주몽에게 지니게 하면 특수방어가 올라가는 비늘. 연한 분홍색으로 빛난다.', 'Doubles Clamperl’s Special Defense. Traded on a Clamperl: Holder evolves into Gorebyss.'),
    (203, 'deep-sea-tooth', '심해의이빨', 'species-specific', 90, '진주몽에게 지니게 하면 특수공격이 올라가는 이빨. 날카로운 은색으로 빛난다.', 'Doubles Clamperl’s Special Attack. Traded on a Clamperl: Holder evolves into Huntail.'),
    (2250, 'delphoxite', NULL, 'mega-stones', 80, NULL, NULL),
    (257, 'destiny-knot', '빨간실', 'held-items', 10, '가늘고 긴 새빨간 실. 지니게 하면 자신이 헤롱헤롱해졌을 때 상대도 헤롱헤롱해지게 된다.', 'Held: Infatuates opposing Pokémon when holder is inflicted with infatuation.'),
    (805, 'diancite', '디안시나이트', 'mega-stones', 80, '디안시에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Diancie to Mega Evolve into Mega Diancie.'),
    (56, 'dire-hit', '크리티컬커터', 'stat-boosts', 30, '급소 명중률이 크게 올라간다. 한 번밖에 쓸 수 없다. 포켓몬을 볼에 넣어버리면 원래대로 되돌아간다.', 'Increases the chance of a critical hit in battle.  Raises happiness.'),
    (563, 'douse-drive', '아쿠아카세트', 'species-specific', 70, '게노세크트에게 지니게 하면 테크노버스터라는 기술이 물타입으로 바뀌는 카세트.', 'Grants Genesect a blue, Water-type Techno Blast.'),
    (288, 'draco-plate', '용의플레이트', 'plates', 90, '드래곤타입의 석판. 지니게 하면 드래곤타입 기술의 위력이 강해진다.', 'Held: Dragon-Type moves from holder do 20% more damage. Changes Arceus’s and Judgment’s type to Dragon.'),
    (2256, 'dragalgite', NULL, 'mega-stones', 80, NULL, NULL),
    (227, 'dragon-fang', '용의이빨', 'type-enhancement', 70, '단단하고 날카로운 이빨. 지니게 하면 드래곤타입 기술의 위력이 올라간다.', 'Held: Dragon-Type moves from holder do 20% more damage.'),
    (2236, 'dragoninite', NULL, 'mega-stones', 80, NULL, NULL),
    (2259, 'drampanite', NULL, 'mega-stones', 80, NULL, NULL),
    (289, 'dread-plate', '공포플레이트', 'plates', 90, '악타입의 석판. 지니게 하면 악타입 기술의 위력이 강해진다.', 'Held: Dark-Type moves from holder do 20% more damage. Changes Arceus’s and Judgment’s type to Dark.'),
    (282, 'earth-plate', '대지플레이트', 'plates', 90, '땅타입의 석판. 지니게 하면 땅타입 기술의 위력이 강해진다.', 'Held: Ground-Type moves from holder do 20% more damage. Changes Arceus’s and Judgment’s type to Ground.'),
    (2247, 'eelektrossite', NULL, 'mega-stones', 80, NULL, NULL),
    (590, 'eject-button', '탈출버튼', 'held-items', 30, '지니게 하고 기술을 받으면 배틀에서 탈출하여 지닌 포켓몬과 교체할 수 있다.', 'Held: When the holder takes damage from a move, it switches out for a party Pokémon of the Trainer’s choice.'),
    (1177, 'eject-pack', '탈출팩', 'held-items', 50, '지니게 한 포켓몬의 능력이 떨어지면 지닌 포켓몬과 교체한다.', NULL),
    (898, 'electric-seed', '일렉트릭시드', 'held-items', 10, '포켓몬에게 지니게 하면 일렉트릭필드일 때 사용하여 방어가 올라간다.', 'Held: Consumed on Electric Terrain and raises the holder’s Defense by one stage.'),
    (2243, 'emboarite', NULL, 'mega-stones', 80, NULL, NULL),
    (581, 'eviolite', '진화의휘석', 'held-items', 40, '진화의 이상한 덩어리. 지니게 하면 진화 전 포켓몬의 방어와 특수방어가 올라간다.', 'Held: Holder has 1.5× Defense and Special Defense, as long as it’s not fully evolved.'),
    (2244, 'excadrite', NULL, 'mega-stones', 80, NULL, NULL),
    (245, 'expert-belt', '달인의띠', 'held-items', 10, '오래 사용한 까만 띠. 지니게 하면 효과가 뛰어날 때 기술의 위력이 조금 올라간다.', 'Held: Holder’s Super Effective moves do 20% extra damage.'),
    (2105, 'fairy-feather', NULL, 'held-items', NULL, NULL, NULL),
    (2261, 'falinksite', NULL, 'mega-stones', 80, NULL, NULL),
    (2238, 'feraligite', NULL, 'mega-stones', 80, NULL, NULL),
    (136, 'figy-berry', '무화열매', 'picky-healing', 10, '포켓몬에게 지니게 하면 위급할 때 HP를 회복한다. 싫어하는 맛이면 혼란에 빠진다.', 'Held: Consumed at 1/2 max HP to restore 1/8 max HP. Confuses Pokémon that dislike spicy flavor.'),
    (280, 'fist-plate', '주먹플레이트', 'plates', 90, '격투타입의 석판. 지니게 하면 격투타입 기술의 위력이 강해진다.', 'Held: Fighting-Type moves from holder do 20% more damage. Changes Arceus’s and Judgment’s type to Fighting.'),
