    (801, 'slowbronite', '야도란나이트', 'mega-stones', 80, '야도란에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Slowbro to Mega Evolve into Mega Slowbro.'),
    (205, 'smoke-ball', '연막탄', 'held-items', 30, '지니게 한 포켓몬은 야생 포켓몬과의 배틀에서 반드시 도망칠 수 있다.', 'Held: Allows the Holder to escape from any wild battle.'),
    (260, 'smooth-rock', '보송보송바위', 'held-items', 10, '지니게 한 포켓몬이 모래바람을 쓰면 여느 때보다 모래바람의 시간이 길어진다.', 'Held: Sandstorm by the holder lasts 8 rounds instead of 5.'),
    (689, 'snowball', '눈덩이', 'held-items', 30, '단 한 번 쓰면 없어지는 눈덩이. 지니게 하고 얼음 기술을 받으면 공격이 올라간다.', 'Held: If the holder is hit by a damaging Ice move, raises its Attack by one stage.'),
    (214, 'soft-sand', '부드러운모래', 'type-enhancement', 10, '만지면 보슬보슬한 모래. 지니게 하면 땅타입 기술의 위력이 올라간다.', 'Held: Ground-Type moves from holder do 20% more damage.'),
    (202, 'soul-dew', '마음의물방울', 'species-specific', 30, '라티오스나 라티아스에게 지니게 하면 에스퍼와 드래곤타입 기술의 위력이 올라가는 이상한 구슬.', 'Raises Latias and Latios’s Special Attack and Special Defense by 50%.'),
    (224, 'spell-tag', '저주의부적', 'type-enhancement', 30, '괴상하고 으스스한 부적. 지니게 하면 고스트타입 기술의 위력이 올라간다.', 'Held: Ghost-Type moves from holder do 20% more damage.'),
    (276, 'splash-plate', '물방울플레이트', 'plates', 90, '물타입의 석판. 지니게 하면 물타입 기술의 위력이 강해진다.', 'Held: Water-Type moves from holder do 20% more damage. Changes Arceus’s and Judgment’s type to Water.'),
    (287, 'spooky-plate', '원령플레이트', 'plates', 90, '고스트타입의 석판. 지니게 하면 고스트타입 기술의 위력이 강해진다.', 'Held: Ghost-Type moves from holder do 20% more damage. Changes Arceus’s and Judgment’s type to Ghost.'),
    (2266, 'staraptite', NULL, 'mega-stones', 80, NULL, NULL),
    (184, 'starf-berry', '스타열매', 'in-a-pinch', 10, '포켓몬에게 지니게 하면 위급할 때 능력 중의 하나가 크게 올라간다.', 'Held: Consumed at 1/4 max HP to boost a random stat by two stages.'),
    (2235, 'starminite', NULL, 'mega-stones', 80, NULL, NULL),
    (802, 'steelixite', '강철톤나이트', 'mega-stones', 80, '강철톤에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Steelix to Mega Evolve into Mega Steelix.'),
    (236, 'stick', '대파', 'species-specific', 60, '매우 길고 단단한 줄기. 파오리에게 지니게 하면 기술이 급소에 맞기 쉬워진다.', 'Raises Farfetch’d’s critical hit ratio by two stages.'),
    (265, 'sticky-barb', '끈적끈적바늘', 'bad-held-items', 80, '지니게 하면 매 턴 데미지를 입는다. 자신에게 접촉해온 상대에게 들러붙기도 한다.', 'Held: Holder takes 1/8 (12.5%) its max HP at the end of each turn. When the holder is hit by a contact move, the attacking Pokémon takes 1/8 its max HP in damage and receive the item if not holding one.'),
    (286, 'stone-plate', '암석플레이트', 'plates', 90, '바위타입의 석판. 지니게 하면 바위타입 기술의 위력이 강해진다.', 'Held: Rock-Type moves from holder do 20% more damage. Changes Arceus’s and Judgment’s type to Rock.'),
    (793, 'swampertite', '대짱이나이트', 'mega-stones', 80, '대짱이에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Swampert to Mega Evolve into Mega Swampert.'),
    (171, 'tanga-berry', '리체열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 벌레 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Bug-type attack to halve the damage.'),
    (2276, 'tatsugirinite', NULL, 'mega-stones', 80, NULL, NULL),
    (896, 'terrain-extender', '그라운드코트', 'held-items', 60, '지니게 한 포켓몬이 기술이나 특성으로 필드를 사용했을 때 여느 때보다 긴 시간 동안 지속된다.', 'Held: Extends the holder’s Terrain effects to 8 turns.'),
    (235, 'thick-club', '굵은뼈', 'species-specific', 90, '무언가의 단단한 뼈. 탕구리 혹은 텅구리에게 지니게 하면 공격이 올라간다.', 'Doubles Cubone or Marowak’s Attack.'),
    (1176, 'throat-spray', '목스프레이', 'held-items', 30, '소리 기술을 사용하면 특수공격이 올라간다.', NULL),
    (249, 'toxic-orb', '맹독구슬', 'bad-held-items', 30, '만지면 독을 발산하는 이상한 구슬. 지니게 하면 배틀 중에 맹독 상태가 된다.', 'Held: Inflicts Toxic on the holder at the end of the turn. Activates after Poison damage would occur.'),
    (281, 'toxic-plate', '맹독플레이트', 'plates', 90, '독타입의 석판. 지니게 하면 독타입 기술의 위력이 강해진다.', 'Held: Poison-Type moves from holder do 20% more damage. Changes Arceus’s and Judgment’s type to Poison.'),
    (225, 'twisted-spoon', '휘어진스푼', 'type-enhancement', 30, '염동력을 담은 숟가락. 지니게 하면 에스퍼타입 기술의 위력이 올라간다.', 'Held: Psychic-Type moves from holder do 20% more damage.'),
    (708, 'tyranitarite', '마기라스나이트', 'mega-stones', 80, '마기라스에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Tyranitar to Mega Evolve into Mega Tyranitar.'),
    (1181, 'utility-umbrella', '만능우산', 'held-items', 60, '지니게 한 포켓몬은 비와 햇살이 강할 때의 영향을 받지 않게 된다.', NULL),
    (698, 'venusaurite', '이상해꽃나이트', 'mega-stones', 80, '이상해꽃에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Venusaur to Mega Evolve into Mega Venusaur.'),
    (2234, 'victreebelite', NULL, 'mega-stones', 80, NULL, NULL),
    (163, 'wacan-berry', '초나열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 전기 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Electric-type attack to halve the damage.'),
    (294, 'wave-incense', '잔물결향로', 'type-enhancement', 10, '이상한 향기의 향로. 지니게 하면 물타입 기술의 위력이 올라간다.', 'Held: Water-Type moves from holder do 20% more damage. Breeding: Mantine begets a Mantyke Egg.'),
    (682, 'weakness-policy', '약점보험', 'held-items', 80, '약점을 공격당했을 때 공격과 특수공격이 각각 크게 올라간다.', 'Held: When the holder is hit by a super effective move, its Attack and Special Attack raise by two stages.'),
    (2106, 'wellspring-mask', NULL, 'held-items', NULL, NULL, NULL),
    (191, 'white-herb', '하양허브', 'held-items', 10, '지니게 한 포켓몬의 능력이 떨어졌을 때 한 번만 원래 상태로 돌아온다.', 'Held: Resets all lowered stats to normal at end of turn. Consumed after use.'),
    (242, 'wide-lens', '광각렌즈', 'held-items', 10, '물건이 크게 보이는 렌즈. 지니게 하면 기술의 명중률이 조금 올라간다.', 'Held: Provides a 1/10 (10%) boost in accuracy to the holder.'),
    (137, 'wiki-berry', '위키열매', 'picky-healing', 10, '포켓몬에게 지니게 하면 위급할 때 HP를 회복한다. 싫어하는 맛이면 혼란에 빠진다.', 'Held: Consumed at 1/2 max HP to restore 1/8 max HP. Confuses Pokémon that dislike dry flavor.'),
    (244, 'wise-glasses', '박식안경', 'held-items', 10, '두꺼운 렌즈를 붙인 안경. 지니게 하면 특수 기술의 위력이 조금 올라간다.', 'Held: Boosts the damage of special moves used by the holder by 1/10 (10%).'),
    (60, 'x-accuracy', '잘-맞히기', 'stat-boosts', 30, '배틀 중인 포켓몬의 명중률을 크게 올리는 도구. 포켓몬을 볼에 넣어버리면 원래대로 되돌아간다.', 'Raises accuracy by one stage in battle.  Raises happiness.'),
    (57, 'x-attack', '플러스파워', 'stat-boosts', 30, '배틀 중인 포켓몬의 공격을 크게 올리는 도구. 포켓몬을 볼에 넣어버리면 원래대로 되돌아간다.', 'Raises Attack by one stage in battle.  Raises happiness.'),
    (58, 'x-defense', '디펜드업', 'stat-boosts', 30, '배틀 중인 포켓몬의 방어를 크게 올리는 도구. 포켓몬을 볼에 넣어버리면 원래대로 되돌아간다.', 'Raises Defense by one stage in battle.  Raises happiness.'),
    (61, 'x-sp-atk', '스페셜업', 'stat-boosts', 30, '배틀 중인 포켓몬의 특수공격을 크게 올리는 도구. 포켓몬을 볼에 넣어버리면 원래대로 되돌아간다.', 'Raises Special Attack by one stage in battle.  Raises happiness.'),
    (62, 'x-sp-def', '스페셜가드', 'stat-boosts', 30, '배틀 중인 포켓몬의 특수방어를 크게 올리는 도구. 포켓몬을 볼에 넣어버리면 원래대로 되돌아간다.', 'Raises Special Defense by one stage in battle.  Raises happiness.'),
    (59, 'x-speed', '스피드업', 'stat-boosts', 30, '배틀 중인 포켓몬의 스피드를 크게 올리는 도구. 포켓몬을 볼에 넣어버리면 원래대로 되돌아간다.', 'Raises Speed by one stage in battle.  Raises happiness.'),
    (165, 'yache-berry', '플카열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 얼음 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Ice-type attack to halve the damage.'),
    (890, 'yellow-nectar', '진노랑꿀', 'species-specific', 10, '멜레멜레 화원에서 손에 넣은 꽃의 꿀. 특정 포켓몬의 모습을 바꾼다.', 'Changes Oricorio to Pom-Pom Style.'),
    (277, 'zap-plate', '우레플레이트', 'plates', 90, '전기타입의 석판. 지니게 하면 전기타입 기술의 위력이 강해진다.', 'Held: Electric-Type moves from holder do 20% more damage. Changes Arceus’s and Judgment’s type to Electric.'),
    (2260, 'zeraorite', NULL, 'mega-stones', 80, NULL, NULL),
    (253, 'zoom-lens', '포커스렌즈', 'held-items', 10, '지니게 한 포켓몬이 상대보다도 행동하는 것이 늦을 때 기술이 명중하기 쉬워진다.', 'Held: Provides a 1/5 (20%) boost in accuracy if the holder moves after the target.'),
    (2258, 'zygardite', NULL, 'mega-stones', 80, NULL, NULL);
